const fs = require('node:fs');
const cp = require('node:child_process');
const crypto = require('node:crypto');
const path = require('node:path');
const root = '/workspaces/rust-service-storage-optimization';
const owned = '/tmp/sea-storage-overhead-N5913w';
const head = '32ee6e92c87b82c23948d23d52db4c94670743c3';
const mode = process.argv[2];
const git = (...args) => cp.execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim();
const hash = file => crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
if (process.cwd() !== root || git('rev-parse', 'HEAD') !== head || git('branch', '--show-current') !== 'rust-service-storage-optimization') throw Error('checkout mismatch');
const baseline = path.join(owned, 'baseline');
const candidate = path.join(root, 'rust-service/target/release/storage-pipeline');
if (mode === 'baseline') {
    if (git('status', '--porcelain')) throw Error('baseline requires clean tree');
    fs.copyFileSync(candidate, baseline, fs.constants.COPYFILE_EXCL);
    fs.chmodSync(baseline, 0o755);
}
const sources = ['rust-service/Cargo.lock', 'rust-service/crates/sea-benchmarks/src/bin/storage-pipeline.rs', 'rust-service/crates/sea-sequencer/src/pipeline.rs', 'rust-service/crates/sea-sequencer/src/session.rs', 'rust-service/crates/sea-sequencer/src/fault_tests.rs'];
const evidence = {
    head, branch: git('branch', '--show-current'), cwd: root, mode,
    started: new Date().toISOString(), command: `node ${__filename} ${mode}`,
    collector: fs.readFileSync(__filename, 'utf8'),
    source_sha256: Object.fromEntries(sources.map(file => [file, hash(path.join(root, file))])),
    binaries: Object.fromEntries((mode === 'baseline' ? [['baseline', baseline]] : [['baseline', baseline], ['candidate', candidate]]).map(([version, file]) => [version, {path:file, sha256:hash(file)}])),
    rustc: cp.execFileSync('rustc', ['--version'], {encoding:'utf8'}).trim(),
    kernel: cp.execFileSync('uname', ['-a'], {encoding:'utf8'}).trim(),
    cpu_max: fs.readFileSync('/sys/fs/cgroup/cpu.max', 'utf8').trim(),
    environment: Object.fromEntries(Object.entries(process.env).filter(([key]) => /^(RUST|CARGO|TOKIO)/.test(key))),
    samples: []
};
const directory = path.join(root, 'rust-service/measurements/2026-09-20/storage-overhead');
fs.mkdirSync(directory, {recursive:true});
const output = path.join(directory, `${mode}.json`);
if (fs.existsSync(output)) throw Error('evidence already exists');
for (let repetition = 1; repetition <= 3; repetition++) {
    const cells = ['memory', 'buffered-file', 'durable-file'].flatMap(backend => [64,8192].flatMap(bytes => [1,128].map(window => ({backend,bytes,window}))));
    if (repetition === 2) cells.reverse();
    for (const {backend, bytes, window} of cells) {
        const versions = mode === 'baseline' ? ['baseline'] : repetition === 2 ? ['candidate','baseline'] : ['baseline','candidate'];
        for (const version of versions) {
            const binary = version === 'baseline' ? baseline : candidate;
            const args = [backend, String(bytes), String(window), path.join(root, 'rust-service/target/storage-overhead-data')];
            const started = new Date().toISOString();
            const result = cp.spawnSync(binary, args, {cwd:root, encoding:'utf8', timeout:180000});
            const rows = result.stdout.trim().split('\n').filter(Boolean).map(row => JSON.parse(row));
            evidence.samples.push({version,repetition,started,command:[binary,...args],status:result.status,signal:result.signal,stderr:result.stderr,rows});
            fs.writeFileSync(output, JSON.stringify(evidence));
            if (result.status !== 0 || rows.length !== 2 || rows.some(row => row.verified_deliveries !== row.operations || !row.verified_order)) throw Error(`failed cell ${backend} ${bytes} ${window}: ${result.stderr}`);
            console.log(mode, repetition, version, backend, bytes, window, rows[1].operations_per_second.toFixed(1));
        }
    }
}
evidence.finished = new Date().toISOString();
fs.writeFileSync(output, JSON.stringify(evidence));
